import{_ as d,o as r,c as a,a3 as e}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"老饕需求一览-jnk","description":"","frontmatter":{"translationSource":{"title":"老饕需求一览-jnk","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=D6G6MQwnB9jEIcQ0lIsfku","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/gourmand-requirements-overview-jnk"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/gourmand-requirements-overview-jnk"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/gourmand-requirements-overview-jnk"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/gourmand-requirements-overview-jnk"}]]},"headers":[],"relativePath":"zh/gourmand-requirements-overview-jnk.md","filePath":"zh/page-D6G6MQwnB9jEIcQ0lIsfku.md"}'),s={name:"zh/gourmand-requirements-overview-jnk.md"};function o(n,t,h,i,l,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<div class="logistics-content"><span class="logistics-source-anchor" id="老饕需求一览-jnk" aria-hidden="true"></span><h1 id="老饕需求一览-jnk" tabindex="-1">老饕需求一览-jnk <a class="header-anchor" href="#老饕需求一览-jnk" aria-label="Permalink to &quot;老饕需求一览-jnk&quot;">​</a></h1><blockquote><p>源页面 ID：<code>D6G6MQwnB9jEIcQ0lIsfku</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=D6G6MQwnB9jEIcQ0lIsfku" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-NrEhNYNnxNPH2PNBjYg2IQ"></span></p><span class="logistics-source-anchor" id="客栈老饕需求一览" aria-hidden="true"></span><h2 id="客栈老饕需求一览" tabindex="-1">客栈老饕需求一览 <a class="header-anchor" href="#客栈老饕需求一览" aria-label="Permalink to &quot;客栈老饕需求一览&quot;">​</a></h2><blockquote><p>本文件由 AI 整理，内容取自akedata内数据表，供查菜时参考。</p></blockquote><p><span id="source-block-fM5MrXVZ6uIjgjeH1viPFK"></span></p><span class="logistics-source-anchor" id="怎么读" aria-hidden="true"></span><h3 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h3><p>每位老饕都有两层：</p><ol><li><p><strong>客人级要求</strong> —— 只要菜单里有一道菜能满足它，这位客人就<strong>可能出现</strong>；</p></li><li><p><strong>具体需求</strong> —— 他真的开口时，从这一层里<strong>随机抽</strong>，可能正好是你做不出来的那条。</p></li></ol><p>所以菜单能覆盖到的「客人类」越多、每一类里能做的条数越多，被满足的概率就越高。</p><p>条件里的符号：</p><table tabindex="0"><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>+</td><td>同一道菜要<strong>同时</strong>满足（例：汤羹 + 含优质鳞肉）</td></tr><tr><td>且</td><td>几个条件<strong>都要</strong>满足</td></tr><tr><td>或</td><td>几个条件<strong>任选其一</strong>（通常是普通食材 / 优质食材两档）</td></tr><tr><td>不要</td><td>必须<strong>不</strong>含 / 不是</td></tr><tr><td>（饮品）</td><td>这条要的是饮品，不是菜</td></tr></tbody></table><hr><p><span id="source-block-m5bg0gq4LVwbsmLJOl8236"></span></p><span class="logistics-source-anchor" id="一、普通老饕-7-种" aria-hidden="true"></span><h3 id="一、普通老饕-7-种" tabindex="-1">一、普通老饕（7 种） <a class="header-anchor" href="#一、普通老饕-7-种" aria-label="Permalink to &quot;一、普通老饕（7 种）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>类型</th><th>客人级要求</th><th>会说几句</th></tr></thead><tbody><tr><td>1</td><td>男农夫</td><td>含面粉</td><td>6</td></tr><tr><td>2</td><td>女农夫</td><td>（含鳞肉） 或 （含优质鳞肉）</td><td>6</td></tr><tr><td>3</td><td>壮汉工人</td><td>（滋补） 或 （汤羹）</td><td>6</td></tr><tr><td>4</td><td>女工人</td><td>（美观） 或 （甜品）</td><td>6</td></tr><tr><td>5</td><td>男工人</td><td>（含肉块） 或 （含优质肉块）</td><td>8</td></tr><tr><td>6</td><td>男孩学生</td><td>菜肴</td><td>4</td></tr><tr><td>7</td><td>女孩学生</td><td>甜品</td><td>4</td></tr></tbody></table><p><span id="source-block-QpOM2ta9jkiIDP0IoTJ1YT"></span></p><span class="logistics-source-anchor" id="普1-·-男农夫" aria-hidden="true"></span><h4 id="普1-·-男农夫" tabindex="-1">普1 · 男农夫 <a class="header-anchor" href="#普1-·-男农夫" aria-label="Permalink to &quot;普1 · 男农夫&quot;">​</a></h4><p><strong>客人级要求</strong>：含面粉</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「来些面食，多放盐，我口味重。」</td><td>咸 + 含面粉</td></tr><tr><td>2</td><td>「还有没有不带鳞腥味的面食？」</td><td>（含面粉） 且 （不要鲜）</td></tr><tr><td>3</td><td>「我想想，炒个菜吧，越辣越好。」</td><td>辣 + 菜肴</td></tr><tr><td>4</td><td>「咸的辣的都行，随便来些好吃的。」</td><td>（咸） 或 （辣）</td></tr><tr><td>5</td><td>「这两天牙疼，别上酸的。」</td><td>不要酸</td></tr><tr><td>6</td><td>「不太甜的点心吧，在刷体脂。」</td><td>（甜品） 且 （不要甜）</td></tr></tbody></table><p><span id="source-block-H3Wcyes826e5qjy8LQwHpb"></span></p><span class="logistics-source-anchor" id="普2-·-女农夫" aria-hidden="true"></span><h4 id="普2-·-女农夫" tabindex="-1">普2 · 女农夫 <a class="header-anchor" href="#普2-·-女农夫" aria-label="Permalink to &quot;普2 · 女农夫&quot;">​</a></h4><p><strong>客人级要求</strong>：（含鳞肉） 或 （含优质鳞肉）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「果然鳞还是要吃新鲜的……」</td><td>（鲜 + 含鳞肉） 或 （鲜 + 含优质鳞肉）</td></tr><tr><td>2</td><td>「有没有“鳞游水中”？就是鳞汤啦。」</td><td>汤羹 + 含优质鳞肉</td></tr><tr><td>3</td><td>「想吃水产……会不会很麻烦？」</td><td>水产</td></tr><tr><td>4</td><td>「锅气十足的菜，啊，千万不要辣。」</td><td>（菜肴） 且 （不要辣）</td></tr><tr><td>5</td><td>「酸酸甜甜，果汁之类的有没有？」</td><td>果香（饮品）</td></tr><tr><td>6</td><td>「再来点喝的，但不要茶，会失眠。」</td><td>不要茶香（饮品）</td></tr></tbody></table><p><span id="source-block-NvstCkNHmqZdz4UIlDGDgI"></span></p><span class="logistics-source-anchor" id="普3-·-壮汉工人" aria-hidden="true"></span><h4 id="普3-·-壮汉工人" tabindex="-1">普3 · 壮汉工人 <a class="header-anchor" href="#普3-·-壮汉工人" aria-label="Permalink to &quot;普3 · 壮汉工人&quot;">​</a></h4><p><strong>客人级要求</strong>：（滋补） 或 （汤羹）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「来份汤，要清淡。」</td><td>（汤羹） 且 （不要辣） 且 （不要咸）</td></tr><tr><td>2</td><td>「素菜一道。」</td><td>素食 + 菜肴</td></tr><tr><td>3</td><td>「滋补身心的良膳，来一道。」</td><td>滋补</td></tr><tr><td>4</td><td>「清爽无油的汤羹，有吗？」</td><td>（汤羹） 且 （不要含菜籽油）</td></tr><tr><td>5</td><td>「香茗一杯。」</td><td>茶香（饮品）</td></tr><tr><td>6</td><td>「来杯喝的，谨记，我滴酒不沾。」</td><td>不要酒香（饮品）</td></tr></tbody></table><p><span id="source-block-NGQDPXOMc4Pl6QVJms6wQL"></span></p><span class="logistics-source-anchor" id="普4-·-女工人" aria-hidden="true"></span><h4 id="普4-·-女工人" tabindex="-1">普4 · 女工人 <a class="header-anchor" href="#普4-·-女工人" aria-label="Permalink to &quot;普4 · 女工人&quot;">​</a></h4><p><strong>客人级要求</strong>：（美观） 或 （甜品）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「有没有好看、能出片的菜式？」</td><td>美观</td></tr><tr><td>2</td><td>「嗯……想吃甜品，最好有点酸。」</td><td>（甜品） 且 （酸）</td></tr><tr><td>3</td><td>「……吃点甜品吧，但别有面粉哦。」</td><td>（甜品） 且 （不要含面粉）</td></tr><tr><td>4</td><td>「想吃很雅致……很有故事的菜式。」</td><td>雅致</td></tr><tr><td>5</td><td>「来一些不带水产的汤羹。」</td><td>（汤羹） 且 （不要水产）</td></tr><tr><td>6</td><td>「鲜则生腥，不是这种的都可以。」</td><td>不要鲜</td></tr></tbody></table><p><span id="source-block-9dixN2BUnMnVRaEpcPb5ex"></span></p><span class="logistics-source-anchor" id="普5-·-男工人" aria-hidden="true"></span><h4 id="普5-·-男工人" tabindex="-1">普5 · 男工人 <a class="header-anchor" href="#普5-·-男工人" aria-label="Permalink to &quot;普5 · 男工人&quot;">​</a></h4><p><strong>客人级要求</strong>：（含肉块） 或 （含优质肉块）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「碳水！肉！拉满！」</td><td>（主食 + 含肉块） 或 （主食 + 含优质肉块）</td></tr><tr><td>2</td><td>「上好的肉！做点菜！」</td><td>菜肴 + 含优质肉块</td></tr><tr><td>3</td><td>「来点汤，要酸口，促消化。」</td><td>酸 + 汤羹</td></tr><tr><td>4</td><td>「来份点心，有没有梅子那么酸的！」</td><td>酸 + 甜品</td></tr><tr><td>5</td><td>「随便上点，别是滋补药膳那种就行！」</td><td>不要滋补</td></tr><tr><td>6</td><td>「肉！上肉！不要纯素！」</td><td>（肉食） 且 （不要素食）</td></tr><tr><td>7</td><td>「来，大碗上酒呀！」</td><td>酒香（饮品）</td></tr><tr><td>8</td><td>「来点喝的清清口，别是奶味的就行。」</td><td>不要奶香（饮品）</td></tr></tbody></table><p><span id="source-block-qrrxzQHjF3kEqy4N50Sb2P"></span></p><span class="logistics-source-anchor" id="普6-·-男孩学生" aria-hidden="true"></span><h4 id="普6-·-男孩学生" tabindex="-1">普6 · 男孩学生 <a class="header-anchor" href="#普6-·-男孩学生" aria-label="Permalink to &quot;普6 · 男孩学生&quot;">​</a></h4><p><strong>客人级要求</strong>：菜肴</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「给我上一道菜肴。」</td><td>菜肴</td></tr><tr><td>2</td><td>「给我上一道茄果的菜肴。」</td><td>菜肴 + 含茄果</td></tr><tr><td>3</td><td>「随便来点什么，但不要稻谷类的。」</td><td>不要含金石稻</td></tr><tr><td>4</td><td>「随便来点什么，但不要甜品的。」</td><td>不要甜品</td></tr></tbody></table><p><span id="source-block-vHONVVIIKSSekdQQd4D2qm"></span></p><span class="logistics-source-anchor" id="普7-·-女孩学生" aria-hidden="true"></span><h4 id="普7-·-女孩学生" tabindex="-1">普7 · 女孩学生 <a class="header-anchor" href="#普7-·-女孩学生" aria-label="Permalink to &quot;普7 · 女孩学生&quot;">​</a></h4><p><strong>客人级要求</strong>：甜品</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「请给我甜品。」</td><td>甜品</td></tr><tr><td>2</td><td>「请给我甜品，不要有砂糖。」</td><td>（甜品） 且 （不要含砂糖）</td></tr><tr><td>3</td><td>「请给我甜品，不要有淀粉。」</td><td>（甜品） 且 （不要含淀粉）</td></tr><tr><td>4</td><td>「请随意给我上点什么，不要是主食。」</td><td>不要主食</td></tr></tbody></table><hr><p><span id="source-block-WtNcLNlYpWwgKCI536SBqT"></span></p><span class="logistics-source-anchor" id="二、特殊客-15-种" aria-hidden="true"></span><h3 id="二、特殊客-15-种" tabindex="-1">二、特殊客（15 种） <a class="header-anchor" href="#二、特殊客-15-种" aria-label="Permalink to &quot;二、特殊客（15 种）&quot;">​</a></h3><p>活动期出现的客人。门槛同样只看「客人级要求」，来了以后按各自的几句随机。</p><p>（有些角色设定和普通老饕重名，比如「壮汉工人」两类都有，按 普/特 + 编号 区分即可。）</p><table tabindex="0"><thead><tr><th>#</th><th>类型</th><th>客人级要求</th><th>会说几句</th></tr></thead><tbody><tr><td>1</td><td>壮汉工人</td><td>主食</td><td>5</td></tr><tr><td>2</td><td>胖男教师</td><td>菜肴</td><td>5</td></tr><tr><td>3</td><td>孩童农夫</td><td>甜品</td><td>5</td></tr><tr><td>4</td><td>老者农夫</td><td>汤羹</td><td>5</td></tr><tr><td>5</td><td>男孩学生</td><td>鲜</td><td>5</td></tr><tr><td>6</td><td>男农夫</td><td>咸</td><td>5</td></tr><tr><td>7</td><td>男孩工程师</td><td>辣</td><td>5</td></tr><tr><td>8</td><td>孩童农夫（女）</td><td>甜</td><td>5</td></tr><tr><td>9</td><td>男工程师</td><td>酸</td><td>5</td></tr><tr><td>10</td><td>男工人</td><td>（肉食） 或 （含肉块） 或 （含优质肉块）</td><td>5</td></tr><tr><td>11</td><td>女孩学生</td><td>（素食） 或 （含多味菇） 或 （含优质多味菇）</td><td>5</td></tr><tr><td>12</td><td>女农夫</td><td>（水产） 或 （含鳞肉） 或 （含优质鳞肉）</td><td>5</td></tr><tr><td>13</td><td>女孩工程师</td><td>（滋补） 或 （含青叶莓） 或 （含优质青叶莓）</td><td>5</td></tr><tr><td>14</td><td>女工人</td><td>（美观） 或 （含一百三十香）</td><td>4</td></tr><tr><td>15</td><td>女教师</td><td>（雅致） 或 （含球豆）</td><td>4</td></tr></tbody></table><p><span id="source-block-3dqldgoluj6m22d5CTYGeF"></span></p><span class="logistics-source-anchor" id="特1-·-壮汉工人" aria-hidden="true"></span><h4 id="特1-·-壮汉工人" tabindex="-1">特1 · 壮汉工人 <a class="header-anchor" href="#特1-·-壮汉工人" aria-label="Permalink to &quot;特1 · 壮汉工人&quot;">​</a></h4><p><strong>客人级要求</strong>：主食</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「充充碳吧，我是说，米饭。」</td><td>主食 + 含金石稻</td></tr><tr><td>2</td><td>「补点碳水，来点够咸的。」</td><td>咸 + 主食</td></tr><tr><td>3</td><td>「碳水碳水，来点够鲜的。」</td><td>鲜 + 主食</td></tr><tr><td>4</td><td>「管饱的碳水，但别辣。」</td><td>（主食） 且 （不要辣）</td></tr><tr><td>5</td><td>「我要不花哨且管饱的碳水！」</td><td>（主食） 且 （不要美观） 且 （不要雅致）</td></tr></tbody></table><p><span id="source-block-mQckZVzPOAceawOVra5kMT"></span></p><span class="logistics-source-anchor" id="特2-·-胖男教师" aria-hidden="true"></span><h4 id="特2-·-胖男教师" tabindex="-1">特2 · 胖男教师 <a class="header-anchor" href="#特2-·-胖男教师" aria-label="Permalink to &quot;特2 · 胖男教师&quot;">​</a></h4><p><strong>客人级要求</strong>：菜肴</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「菜肴之美，在于无鳞不成席呀。」</td><td>（菜肴 + 含鳞肉） 或 （菜肴 + 含优质鳞肉）</td></tr><tr><td>2</td><td>「菜肴之妙，在于远离菌菇呀。」</td><td>（菜肴） 且 （不要含多味菇） 且 （不要含优质多味菇）</td></tr><tr><td>3</td><td>「菜肴之礼，在于以酸开胃呀。」</td><td>酸 + 菜肴</td></tr><tr><td>4</td><td>「菜肴之勇，在于辛辣之巧呀。」</td><td>辣 + 菜肴</td></tr><tr><td>5</td><td>「菜肴之智，在于远离甜腻呀。」</td><td>（菜肴） 且 （不要甜）</td></tr></tbody></table><p><span id="source-block-pqWofnulCWRAzBh8Kwwfz8"></span></p><span class="logistics-source-anchor" id="特3-·-孩童农夫" aria-hidden="true"></span><h4 id="特3-·-孩童农夫" tabindex="-1">特3 · 孩童农夫 <a class="header-anchor" href="#特3-·-孩童农夫" aria-label="Permalink to &quot;特3 · 孩童农夫&quot;">​</a></h4><p><strong>客人级要求</strong>：甜品</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「那种，有奶香味的甜糕点。」</td><td>（甜品 + 含兽奶） 或 （甜品 + 含优质兽奶）</td></tr><tr><td>2</td><td>「那种，有蛋香味的甜糕点。」</td><td>（甜品 + 含禽蛋） 或 （甜品 + 含优质禽蛋）</td></tr><tr><td>3</td><td>「那种，不会蛀牙的糕点。」</td><td>（甜品） 且 （不要含砂糖）</td></tr><tr><td>4</td><td>「那种，咸咸的美味糕点。」</td><td>咸 + 甜品</td></tr><tr><td>5</td><td>「那些，酸酸甜甜的下午茶糕点。」</td><td>（酸 + 甜品） 或 （甜 + 甜品）</td></tr></tbody></table><p><span id="source-block-8rJ1TtBTx6OVmqiD6ZAEX3"></span></p><span class="logistics-source-anchor" id="特4-·-老者农夫" aria-hidden="true"></span><h4 id="特4-·-老者农夫" tabindex="-1">特4 · 老者农夫 <a class="header-anchor" href="#特4-·-老者农夫" aria-label="Permalink to &quot;特4 · 老者农夫&quot;">​</a></h4><p><strong>客人级要求</strong>：汤羹</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「可有靓汤？莫放球豆。」</td><td>（汤羹） 且 （不要含球豆）</td></tr><tr><td>2</td><td>「可有靓汤？雅致当先。」</td><td>雅致 + 汤羹</td></tr><tr><td>3</td><td>「可有靓汤？需酸解腻。」</td><td>酸 + 汤羹</td></tr><tr><td>4</td><td>「可有靓汤？以鲜当先。」</td><td>鲜 + 汤羹</td></tr><tr><td>5</td><td>「可有靓汤？莫要纯素。」</td><td>（汤羹） 且 （不要素食）</td></tr></tbody></table><p><span id="source-block-q2LVPeqjZ8haGqTSrFrWK8"></span></p><span class="logistics-source-anchor" id="特5-·-男孩学生" aria-hidden="true"></span><h4 id="特5-·-男孩学生" tabindex="-1">特5 · 男孩学生 <a class="header-anchor" href="#特5-·-男孩学生" aria-label="Permalink to &quot;特5 · 男孩学生&quot;">​</a></h4><p><strong>客人级要求</strong>：鲜</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「百膳鲜为先，只是不爱鳞。」</td><td>（鲜） 且 （不要含鳞肉） 且 （不要含优质鳞肉）</td></tr><tr><td>2</td><td>「百膳鲜为先，滋补味更深。」</td><td>（鲜） 且 （滋补）</td></tr><tr><td>3</td><td>「百膳鲜为先，汤羹却下乘。」</td><td>（鲜） 且 （不要汤羹）</td></tr><tr><td>4</td><td>「且来些饮料，唯独不要茶。」</td><td>不要茶香（饮品）</td></tr><tr><td>5</td><td>「且来些饮料，以果味为佳。」</td><td>果香（饮品）</td></tr></tbody></table><p><span id="source-block-AeVb45KJ7TGtlWTAkO51xU"></span></p><span class="logistics-source-anchor" id="特6-·-男农夫" aria-hidden="true"></span><h4 id="特6-·-男农夫" tabindex="-1">特6 · 男农夫 <a class="header-anchor" href="#特6-·-男农夫" aria-label="Permalink to &quot;特6 · 男农夫&quot;">​</a></h4><p><strong>客人级要求</strong>：咸</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「咸口的随意上些，不要汤羹。」</td><td>（咸） 且 （不要汤羹）</td></tr><tr><td>2</td><td>「随意上些，咸一点，不要肉食。」</td><td>（咸） 且 （不要含肉块） 且 （不要含优质肉块）</td></tr><tr><td>3</td><td>「来点少油吃食，但盐要多放。」</td><td>（咸） 且 （不要含菜籽油）</td></tr><tr><td>4</td><td>「随意上些饮品，不要有果味。」</td><td>不要果香（饮品）</td></tr><tr><td>5</td><td>「什么喝的都行，但要清口解腻。」</td><td>茶香 + 饮品（饮品）</td></tr></tbody></table><p><span id="source-block-nbMFYutWTrIXm9qjREGSPn"></span></p><span class="logistics-source-anchor" id="特7-·-男孩工程师" aria-hidden="true"></span><h4 id="特7-·-男孩工程师" tabindex="-1">特7 · 男孩工程师 <a class="header-anchor" href="#特7-·-男孩工程师" aria-label="Permalink to &quot;特7 · 男孩工程师&quot;">​</a></h4><p><strong>客人级要求</strong>：辣</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「啥都行！多辣！不要主食！」</td><td>（辣） 且 （不要主食）</td></tr><tr><td>2</td><td>「上点吃食，重辣不倒牙就行。」</td><td>（辣） 且 （不要酸）</td></tr><tr><td>3</td><td>「肉要上品，而且要辣，很辣！」</td><td>辣 + 含优质肉块</td></tr><tr><td>4</td><td>「喝的！啥都行！但不能醉人！」</td><td>不要酒香（饮品）</td></tr><tr><td>5</td><td>「来杯喝的，别有草叶子味！」</td><td>不要茶香（饮品）</td></tr></tbody></table><p><span id="source-block-STf7YBFXaHs0lsXHBMNgxi"></span></p><span class="logistics-source-anchor" id="特8-·-孩童农夫-女" aria-hidden="true"></span><h4 id="特8-·-孩童农夫-女" tabindex="-1">特8 · 孩童农夫（女） <a class="header-anchor" href="#特8-·-孩童农夫-女" aria-label="Permalink to &quot;特8 · 孩童农夫（女）&quot;">​</a></h4><p><strong>客人级要求</strong>：甜</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「可有甘甜果味之物予我？」</td><td>（甜 + 含青叶莓） 或 （甜 + 含优质青叶莓）</td></tr><tr><td>2</td><td>「可有味甜无肉之物予我？」</td><td>（甜） 且 （不要含肉块） 且 （不要含优质肉块）</td></tr><tr><td>3</td><td>「可有味甜而非糕点之物予我？」</td><td>（甜） 且 （不要甜 + 甜品）</td></tr><tr><td>4</td><td>「可有不辣之饮予我？」</td><td>不要酒香（饮品）</td></tr><tr><td>5</td><td>「可有乳饮予我？」</td><td>奶香（饮品）</td></tr></tbody></table><p><span id="source-block-B8fB1eX777xO23WFVqCsYH"></span></p><span class="logistics-source-anchor" id="特9-·-男工程师" aria-hidden="true"></span><h4 id="特9-·-男工程师" tabindex="-1">特9 · 男工程师 <a class="header-anchor" href="#特9-·-男工程师" aria-label="Permalink to &quot;特9 · 男工程师&quot;">​</a></h4><p><strong>客人级要求</strong>：酸</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「我看……茄果菜式，酸能提味。」</td><td>酸 + 含茄果</td></tr><tr><td>2</td><td>「嗯……鳞肉菜式，要有解腻酸味。」</td><td>（酸 + 含鳞肉） 或 （酸 + 含优质鳞肉）</td></tr><tr><td>3</td><td>「我想……酸味菜肴，不要做成甜品。」</td><td>（酸） 且 （不要甜品）</td></tr><tr><td>4</td><td>「或许……随意饮品？但我乳糖不耐。」</td><td>不要奶香（饮品）</td></tr><tr><td>5</td><td>「没错……理应小酌几杯。」</td><td>酒香（饮品）</td></tr></tbody></table><p><span id="source-block-5GaBJkidjv86lgzE89bcc0"></span></p><span class="logistics-source-anchor" id="特10-·-男工人" aria-hidden="true"></span><h4 id="特10-·-男工人" tabindex="-1">特10 · 男工人 <a class="header-anchor" href="#特10-·-男工人" aria-label="Permalink to &quot;特10 · 男工人&quot;">​</a></h4><p><strong>客人级要求</strong>：（肉食） 或 （含肉块） 或 （含优质肉块）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「肉。」</td><td>肉食</td></tr><tr><td>2</td><td>「好肉。汤不行。」</td><td>（含优质肉块） 且 （不要汤羹）</td></tr><tr><td>3</td><td>「肉。菜肴。」</td><td>（菜肴 + 含肉块） 或 （菜肴 + 含优质肉块）</td></tr><tr><td>4</td><td>「喝的。茶。」</td><td>茶香（饮品）</td></tr><tr><td>5</td><td>「喝的。果味不行。」</td><td>不要果香（饮品）</td></tr></tbody></table><p><span id="source-block-jMMXNZuIW3sID3eH221MXW"></span></p><span class="logistics-source-anchor" id="特11-·-女孩学生" aria-hidden="true"></span><h4 id="特11-·-女孩学生" tabindex="-1">特11 · 女孩学生 <a class="header-anchor" href="#特11-·-女孩学生" aria-label="Permalink to &quot;特11 · 女孩学生&quot;">​</a></h4><p><strong>客人级要求</strong>：（素食） 或 （含多味菇） 或 （含优质多味菇）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「哎你们有没有素的？」</td><td>素食</td></tr><tr><td>2</td><td>「哎你们有没有多味菇的汤？」</td><td>汤羹 + 含优质多味菇</td></tr><tr><td>3</td><td>「哎你们有没有多味菇菜肴？」</td><td>菜肴 + 含优质多味菇</td></tr><tr><td>4</td><td>「哎你们有没有无酒精饮料？」</td><td>不要酒香（饮品）</td></tr><tr><td>5</td><td>「哎你们有没有古典清新饮料？」</td><td>茶香（饮品）</td></tr></tbody></table><p><span id="source-block-YE5g8DTon9ftncAlrMJG6v"></span></p><span class="logistics-source-anchor" id="特12-·-女农夫" aria-hidden="true"></span><h4 id="特12-·-女农夫" tabindex="-1">特12 · 女农夫 <a class="header-anchor" href="#特12-·-女农夫" aria-label="Permalink to &quot;特12 · 女农夫&quot;">​</a></h4><p><strong>客人级要求</strong>：（水产） 或 （含鳞肉） 或 （含优质鳞肉）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「好时节！该吃水中之物！」</td><td>水产</td></tr><tr><td>2</td><td>「上好水产！不要做成汤羹！」</td><td>（含优质鳞肉） 且 （不要汤羹）</td></tr><tr><td>3</td><td>「鳞肉菜式！做成主食！」</td><td>（主食 + 含鳞肉） 或 （主食 + 含优质鳞肉）</td></tr><tr><td>4</td><td>「来点喝的，别有奶腥味。」</td><td>不要奶香（饮品）</td></tr><tr><td>5</td><td>「佐餐饮品来一些，可别让我上头。」</td><td>不要酒香（饮品）</td></tr></tbody></table><p><span id="source-block-wTliPiHptJ0v6GbSxILQTo"></span></p><span class="logistics-source-anchor" id="特13-·-女孩工程师" aria-hidden="true"></span><h4 id="特13-·-女孩工程师" tabindex="-1">特13 · 女孩工程师 <a class="header-anchor" href="#特13-·-女孩工程师" aria-label="Permalink to &quot;特13 · 女孩工程师&quot;">​</a></h4><p><strong>客人级要求</strong>：（滋补） 或 （含青叶莓） 或 （含优质青叶莓）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「吃东西还是要吃滋补的。」</td><td>滋补</td></tr><tr><td>2</td><td>「优质青叶莓还是不适合当主食。」</td><td>（含优质青叶莓） 且 （不要主食）</td></tr><tr><td>3</td><td>「优质青叶莓还是要做成甜品。」</td><td>甜品 + 含优质青叶莓</td></tr><tr><td>4</td><td>「饮品还是得喝有青叶莓的。」</td><td>果香（饮品）</td></tr><tr><td>5</td><td>「这次不喝青叶莓了，喝点奶。」</td><td>奶香（饮品）</td></tr></tbody></table><p><span id="source-block-7dVXOhbqVbR7wIOjB2uerD"></span></p><span class="logistics-source-anchor" id="特14-·-女工人" aria-hidden="true"></span><h4 id="特14-·-女工人" tabindex="-1">特14 · 女工人 <a class="header-anchor" href="#特14-·-女工人" aria-label="Permalink to &quot;特14 · 女工人&quot;">​</a></h4><p><strong>客人级要求</strong>：（美观） 或 （含一百三十香）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「别丑就行，好看最重要。」</td><td>美观</td></tr><tr><td>2</td><td>「让我见识见识一百三十香。」</td><td>含一百三十香</td></tr><tr><td>3</td><td>「菜肴都丑，上点好看的。」</td><td>（美观） 且 （不要菜肴）</td></tr><tr><td>4</td><td>「饮料都挺不错，上果香奶香的吧。」</td><td>（果香） 或 （奶香）（饮品）</td></tr></tbody></table><p><span id="source-block-qjvBtFhmXvU8FyZdSM7x7h"></span></p><span class="logistics-source-anchor" id="特15-·-女教师" aria-hidden="true"></span><h4 id="特15-·-女教师" tabindex="-1">特15 · 女教师 <a class="header-anchor" href="#特15-·-女教师" aria-label="Permalink to &quot;特15 · 女教师&quot;">​</a></h4><p><strong>客人级要求</strong>：（雅致） 或 （含球豆）</p><p><strong>会说这几句</strong>（随机）：</p><table tabindex="0"><thead><tr><th>#</th><th>原话</th><th>条件</th></tr></thead><tbody><tr><td>1</td><td>「夫用膳者，理应雅致为先。」</td><td>雅致</td></tr><tr><td>2</td><td>「夫品汤羹者，理应善用球豆。」</td><td>汤羹 + 含球豆</td></tr><tr><td>3</td><td>「夫擅烹球豆者，理应舍去甜腻。」</td><td>（含球豆） 且 （不要含砂糖）</td></tr><tr><td>4</td><td>「夫好饮者，理应茶酒为先。」</td><td>（茶香） 或 （酒香）（饮品）</td></tr></tbody></table></div>',1)])])}const u=d(s,[["render",o]]);export{b as __pageData,u as default};
